            text: { az: 'Bir dəfə (ən-Nəsai, əl-Kübra 9848).', en: 'Once (an-Nasa’i, al-Kubra 9848).', ru: 'Один раз (ан-Насаи, «аль-Кубра» 9848).', ar: 'مرة (النسائي في الكبرى 9848).', tr: 'Bir kez (Nesâî, el-Kübrâ 9848).' },
